package com.example.planyourtrip.controller;
import com.example.planyourtrip.dto.ExpenseDto; import com.example.planyourtrip.security.AuthUser; import com.example.planyourtrip.service.ExpenseService; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/trips/{tripId}/expenses") public class ExpenseController { private final ExpenseService s; public ExpenseController(ExpenseService s){this.s=s;} @GetMapping List<ExpenseDto> list(@AuthUser Long uid,@PathVariable Long tripId){return s.list(uid,tripId);} @PostMapping ExpenseDto create(@AuthUser Long uid,@PathVariable Long tripId,@Valid @RequestBody ExpenseDto d){return s.create(uid,tripId,d);} @DeleteMapping("/{id}") void delete(@AuthUser Long uid,@PathVariable Long id){s.delete(uid,id);} }
